        return function(ctx)
            local M = {}

            local qualities = {
                "Broken",
                "Refined",
                "Pristine",
                "Divine",
                "Artifact",
                "Transcendent",
            }

            local qualityRank = {
                Broken = 1,
                Refined = 2,
                Pristine = 3,
                Divine = 4,
                Artifact = 5,
                Transcendent = 6,
            }

            local optionMap = {}
            local optionMeta = {}
            local dropdown = nil
            local busy = false
            local attempts = 0
            local lastStatusText = nil

            local cachedResultLabel = nil
            local cachedReforgeRoot = nil
            local lastLabelScan = 0

            local function save()
                if type(ctx.Save) == "function" then
                    pcall(ctx.Save)
                end
            end

            local function notify(title, content, duration)
                if ctx.Notifier and type(ctx.Notifier.new) == "function" then
                    pcall(function()
                        ctx.Notifier.new({
                            Title = title,
                            Content = content,
                            Duration = duration or 4,
                        })
                    end)
                end
            end

            local function canonicalQuality(value)
                local s = string.lower(tostring(value or ""))

                for _, quality in ipairs(qualities) do
                    if string.find(s, string.lower(quality), 1, true) then
                        return quality
                    end
                end

                return nil
            end

            local function normalizePercent(value)
                local n = tonumber(value)
                if not n then
                    return nil
                end

                if n >= -20.05 and n <= 18.05 then
                    return n
                end

                return nil
            end

            local function parsePercent(value)
                local s = tostring(value or "")
                local numberText = string.match(
                    s,
                    "([%+%-]?%d+%.?%d*)%s*%%"
                )

                if numberText then
                    return normalizePercent(tonumber(numberText))
                end

                return nil
            end

            local function inferQuality(percent)
                local p = normalizePercent(percent)
                if p == nil then
                    return nil
                end

                if p >= 15 then
                    return "Transcendent"
                elseif p >= 10 then
                    return "Artifact"
                elseif p >= 5 then
                    return "Divine"
                elseif p >= 0 then
                    return "Pristine"
                elseif p >= -10 then
                    return "Refined"
                elseif p >= -20 then
                    return "Broken"
                end

                return nil
            end

            local function getInventory()
                return ctx.LocalPlayer
                    and ctx.LocalPlayer:FindFirstChild("Inventory")
                    or nil
            end

            local function readItemState(item, allowUI)
                if not item or not item.Parent then
                    return nil, nil
                end

                local quality = nil
                local percent = nil
                local attrs = item:GetAttributes()

                local qualityKeys = {
                    "ReforgeQuality",
                    "QualityName",
                    "Quality",
                    "ReforgeGrade",
                    "QualityGrade",
                }

                local percentKeys = {
                    "ReforgePercent",
                    "ReforgePercentage",
                    "QualityPercent",
                    "QualityPercentage",
                    "ReforgeBonusPercent",
                    "QualityBonusPercent",
                }

                for _, key in ipairs(qualityKeys) do
                    local value = attrs[key]
                    if value ~= nil then
                        quality = canonicalQuality(value)
                        if quality then
                            break
                        end
                    end
                end

                for _, key in ipairs(percentKeys) do
                    local value = attrs[key]
                    if value ~= nil then
                        percent = normalizePercent(value)
                            or parsePercent(value)

                        if percent ~= nil then
                            break
                        end
                    end
                end

                if not quality or percent == nil then
                    for key, value in pairs(attrs) do
                        local keyLower = string.lower(tostring(key))
                        local relevant =
                            string.find(keyLower, "reforge", 1, true)
                            or string.find(keyLower, "quality", 1, true)

                        if relevant then
                            if not quality then
                                quality = canonicalQuality(value)
                            end

                            if percent == nil then
                                percent = normalizePercent(value)
                                    or parsePercent(value)
                            end
                        end
                    end
                end

                if not quality or percent == nil then
                    local inspected = 0

                    for _, child in ipairs(item:GetDescendants()) do
                        if child:IsA("ValueBase") then
                            inspected = inspected + 1
                            if inspected > 80 then
                                break
                            end

                            local keyLower = string.lower(child.Name)
                            local relevant =
                                string.find(keyLower, "reforge", 1, true)
                                or string.find(keyLower, "quality", 1, true)

                            if relevant then
                                local value = child.Value

                                if not quality then
                                    quality = canonicalQuality(value)
                                end

                                if percent == nil then
                                    percent = normalizePercent(value)
                                        or parsePercent(value)
                                end
                            end
                        end
                    end
                end

                if not quality and percent ~= nil then
                    quality = inferQuality(percent)
                end

                if allowUI ~= false then
                    local uiQuality, uiPercent = M.ReadUIState()

                    if uiQuality and uiPercent ~= nil then
                        quality = uiQuality
                        percent = uiPercent
                    end
                end

                return quality, percent
            end

            local function resolveResultLabel(force)
                local playerGui = ctx.LocalPlayer
                    and ctx.LocalPlayer:FindFirstChildOfClass("PlayerGui")
                local main = playerGui and playerGui:FindFirstChild("Main")
                local root = main and main:FindFirstChild("Reforge", true)

                if not root then
                    cachedResultLabel = nil
                    cachedReforgeRoot = nil
                    return nil
                end

                if not force
                    and cachedResultLabel
                    and cachedResultLabel.Parent
                    and cachedReforgeRoot == root then
                    return cachedResultLabel
                end

                -- Avoid repeated full scans if no valid label exists yet.
                if not force
                    and cachedReforgeRoot == root
                    and os.clock() - lastLabelScan < 0.50 then
                    return nil
                end

                lastLabelScan = os.clock()
                cachedReforgeRoot = root
                cachedResultLabel = nil

                local bestLabel = nil
                local bestScore = -math.huge
                local scanned = 0

                for _, gui in ipairs(root:GetDescendants()) do
                    if gui:IsA("TextLabel") or gui:IsA("TextButton") then
                        scanned = scanned + 1
                        if scanned > 500 then
                            break
                        end

                        local visible = true
                        pcall(function()
                            visible = gui.Visible
                        end)

                        if visible then
                            local txt = tostring(gui.Text or "")
                            local quality = canonicalQuality(txt)
                            local percent = parsePercent(txt)

                            if quality and percent ~= nil then
                                local percentCount = 0
                                for _ in string.gmatch(txt, "%%") do
                                    percentCount = percentCount + 1
                                end

                                if percentCount == 1 then
                                    local score = 0

                                    if #txt <= 40 then
                                        score = score + 10
                                    end

                                    pcall(function()
                                        score = score
                                            + math.min(
                                                tonumber(gui.TextSize) or 0,
                                                40
                                            ) * 0.25
                                    end)

                                    pcall(function()
                                        local absY = gui.AbsolutePosition.Y
                                        local rootY = root.AbsolutePosition.Y

                                        if absY <= rootY
                                            + math.max(
                                                root.AbsoluteSize.Y * 0.45,
                                                160
                                            ) then
                                            score = score + 4
                                        end
                                    end)

                                    if score > bestScore then
                                        bestScore = score
                                        bestLabel = gui
                                    end
                                end
                            end
                        end
                    end
                end

                cachedResultLabel = bestLabel
                return bestLabel
            end

            function M.ReadUIState()
                local label = resolveResultLabel(false)

                if label and label.Parent then
                    local txt = tostring(label.Text or "")
                    local quality = canonicalQuality(txt)
                    local percent = parsePercent(txt)

                    if quality and percent ~= nil then
                        return quality, percent
                    end
                end

                return nil, nil
            end

            local function identityHint(item)
                if not item then
                    return nil
                end

                local attrs = item:GetAttributes()
                local keys = {
                    "UUID", "Uid", "UID",
                    "UniqueId", "UniqueID",
                    "ItemId", "ItemID",
                    "InventoryId", "InventoryID",
                }

                for _, key in ipairs(keys) do
                    local value = attrs[key]

                    if value ~= nil then
                        local s = tostring(value)

                        if s ~= "" then
                            if #s > 8 then
                                s = string.sub(s, -8)
                            end

                            return s
                        end
                    end
                end

                return nil
            end

            function M.BuildOptions()
                local inv = getInventory()
                local values = {}
                local counts = {}
                local ordinals = {}

                optionMap = {}
                optionMeta = {}

                if not inv then
                    return { "Select Item" }
                end

                local children = inv:GetChildren()

                for _, item in ipairs(children) do
                    counts[item.Name] = (counts[item.Name] or 0) + 1
                end

                for index, item in ipairs(children) do
                    local baseName = tostring(item.Name)
                    ordinals[baseName] = (ordinals[baseName] or 0) + 1

                    local ordinal = ordinals[baseName]
                    local quality, percent = readItemState(item, false)

                    local buffText = quality or "Unknown"
                    if percent ~= nil then
                        buffText = buffText
                            .. string.format(" %+.2f%%", percent)
                    end

                    local suffix = ""
                    if (counts[baseName] or 0) > 1 then
                        suffix = " #" .. tostring(ordinal)
                    end

                    local hint = identityHint(item)
                    if hint then
                        suffix = suffix .. " [" .. hint .. "]"
                    end

                    local label = baseName
                        .. " | "
                        .. buffText
                        .. suffix

                    if optionMap[label] then
                        label = label .. " @" .. tostring(index)
                    end

                    optionMap[label] = item
                    optionMeta[label] = {
                        Name = baseName,
                        Ordinal = ordinal,
                    }

                    table.insert(values, label)
                end

                table.sort(values)

                if #values == 0 then
                    table.insert(values, "Select Item")
                end

                return values
            end

            local function findItem(selection)
                local value = tostring(selection or "")

                if value == "" or value == "Select Item" then
                    return nil
                end

                local mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                -- Rebuild once if Inventory changed.
                M.BuildOptions()

                mapped = optionMap[value]
                if mapped and mapped.Parent then
                    return mapped
                end

                local inv = getInventory()
                local fallbackName =
                    tostring(ctx.Config.ReforgeItemName or "")

                if inv and fallbackName ~= "" then
                    for _, item in ipairs(inv:GetChildren()) do
                        if item.Name == fallbackName then
                            return item
                        end
                    end
                end

                return nil
            end

            local function selectedItem()
                local selector =
                    tostring(ctx.Config.ReforgeItemSelector or "")

                if selector == "" then
                    selector = tostring(
                        ctx.Config.ReforgeItemName or ""
                    )
                end

                return findItem(selector)
            end

            local function goalState(item)
                local quality, percent = M.ReadUIState()

                if not quality or percent == nil then
                    quality, percent = readItemState(item, false)
                end

                percent = normalizePercent(percent)

                if not quality or percent == nil then
                    return false, quality, percent
                end

                local currentRank = qualityRank[quality] or 0
                local targetRank =
                    qualityRank[ctx.Config.ReforgeTargetQuality] or 0
                local minPercent =
                    tonumber(ctx.Config.ReforgeMinPercent) or 0

                return currentRank >= targetRank
                    and percent >= minPercent,
                    quality,
                    percent
            end

            local function statusText()
                local item = selectedItem()
                local selectedName =
                    item and item.Name
                    or tostring(ctx.Config.ReforgeItemName or "")

                if not item
                    and (selectedName == ""
                        or selectedName == "Select Item") then

                    return "Item: Not selected"
                        .. "\nCurrent: --"
                        .. "\nTarget: "
                        .. tostring(
                            ctx.Config.ReforgeTargetQuality
                                or "Divine"
                        )
                        .. " / "
                        .. string.format(
                            "%+.2f%%",
                            tonumber(
                                ctx.Config.ReforgeMinPercent
                            ) or 0
                        )
                        .. "\nStatus: Waiting for item"
                end

                if not item then
                    return "Item: " .. selectedName
                        .. "\nCurrent: Item not found"
                        .. "\nTarget: "
                        .. tostring(
                            ctx.Config.ReforgeTargetQuality
                                or "Divine"
                        )
                        .. " / "
                        .. string.format(
                            "%+.2f%%",
                            tonumber(
                                ctx.Config.ReforgeMinPercent
                            ) or 0
                        )
                        .. "\nStatus: Waiting for item"
                end

                local goalMet, quality, percent =
                    goalState(item)

                local currentText = quality or "Unknown"

                if percent ~= nil then
                    currentText = currentText
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                else
                    currentText = currentText
                        .. " (waiting for valid Reforge data)"
                end

                local targetText =
                    tostring(
                        ctx.Config.ReforgeTargetQuality
                            or "Divine"
                    )
                    .. " / "
                    .. string.format(
                        "%+.2f%%",
                        tonumber(ctx.Config.ReforgeMinPercent) or 0
                    )

                local status

                if goalMet then
                    status = "Goal Reached ✓"
                elseif ctx.Config.AutoReforge and busy then
                    status = "Reforging..."
                elseif ctx.Config.AutoReforge then
                    status = "Starting..."
                else
                    status = "Ready"
                end

                return "Item: " .. selectedName
                    .. "\nCurrent: " .. currentText
                    .. "\nTarget: " .. targetText
                    .. "\nAttempts: "
                    .. tostring(attempts)
                    .. " / "
                    .. tostring(
                        ctx.Config.ReforgeMaxAttempts or 100
                    )
                    .. "\nStatus: " .. status
            end

            function M.UpdateStatus()
                if not ctx.Paragraph
                    or type(ctx.Paragraph.SetContent)
                        ~= "function" then
                    return
                end

                local ok, content = pcall(statusText)

                if not ok or type(content) ~= "string" then
                    return
                end

                if content == lastStatusText then
                    return
                end

                lastStatusText = content

                pcall(function()
                    ctx.Paragraph:SetContent(content)
                end)
            end

            function M.SetDropdown(obj)
                dropdown = obj
            end

            function M.Select(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                value = tostring(value or "")

                ctx.Config.ReforgeItemSelector = value

                local item = findItem(value)
                ctx.Config.ReforgeItemName =
                    item and item.Name or ""

                cachedResultLabel = nil
                save()
                M.UpdateStatus()
            end

            function M.SetQuality(selected)
                local value =
                    type(selected) == "table"
                    and (selected[1] or next(selected))
                    or selected

                ctx.Config.ReforgeTargetQuality =
                    tostring(value or "Divine")

                save()
                M.UpdateStatus()
            end

            function M.SetMinPercent(value)
                ctx.Config.ReforgeMinPercent =
                    tonumber(value) or 5

                save()
                M.UpdateStatus()
            end

            function M.SetMaxAttempts(value)
                ctx.Config.ReforgeMaxAttempts =
                    math.floor(tonumber(value) or 100)

                save()
                M.UpdateStatus()
            end

            function M.RefreshItems()
                local values = M.BuildOptions()

                if dropdown
                    and type(dropdown.SetValues)
                        == "function" then
                    pcall(function()
                        dropdown:SetValues(values)
                    end)
                end

                M.UpdateStatus()

                notify(
                    "Auto Reforge",
                    "Reforge item list refreshed.",
                    3
                )
            end

            function M.Inspect()
                local item = selectedItem()

                if not item then
                    notify(
                        "Auto Reforge",
                        "No item selected.",
                        3
                    )
                    return
                end

                cachedResultLabel = nil

                local quality, percent =
                    readItemState(item, true)

                local textValue = quality or "Unknown"

                if percent ~= nil then
                    textValue = textValue
                        .. string.format(
                            " (%+.2f%%)",
                            percent
                        )
                end

                notify(
                    "Reforge State",
                    textValue,
                    5
                )

                M.UpdateStatus()
            end

            local function runWorker()
                if busy or not ctx.Config.AutoReforge then
                    return
                end

                busy = true
                attempts = 0
                M.UpdateStatus()

                task.spawn(function()
                    local remotes =
                        ctx.ReplicatedStorage
                            :FindFirstChild("Remotes")
                    local upgradeRemote =
                        remotes
                        and remotes:FindFirstChild("Upgrade")

                    if not upgradeRemote
                        or not upgradeRemote:IsA(
                            "RemoteFunction"
                        ) then

                        ctx.Config.AutoReforge = false
                        busy = false
                        save()
                        M.UpdateStatus()
                        return
                    end

                    local maxAttempts = math.clamp(
                        tonumber(
                            ctx.Config.ReforgeMaxAttempts
                        ) or 100,
                        1,
                        500
                    )

                    local unknownReads = 0

                    while ctx.Config.AutoReforge
                        and attempts < maxAttempts do

                        local item = selectedItem()

                        if not item or not item.Parent then
                            break
                        end

                        local goalMet, quality, percent =
                            goalState(item)

                        if goalMet then
                            break
                        end

                        if quality or percent ~= nil then
                            unknownReads = 0
                        end

                        attempts = attempts + 1
                        M.UpdateStatus()

                        local ok = pcall(function()
                            upgradeRemote:InvokeServer(
                                "Reforge",
                                item
                            )
                        end)

                        if not ok then
                            task.wait(0.75)
                            break
                        end

                        -- Let the game's result label update.
                        task.wait(0.48)

                        M.UpdateStatus()

                        local _, afterQuality, afterPercent =
                            goalState(item)

                        if not afterQuality
                            or afterPercent == nil then

                            unknownReads = unknownReads + 1

                            if unknownReads >= 3 then
                                break
                            end
                        else
                            unknownReads = 0
                        end

                        task.wait(0.10)
                    end

                    ctx.Config.AutoReforge = false
                    busy = false
                    save()
                    M.UpdateStatus()
                end)
            end

            function M.Toggle(value)
                ctx.Config.AutoReforge =
                    value == true

                save()
                M.UpdateStatus()

                if not value then
                    return
                end

                local item = selectedItem()

                if not item then
                    ctx.Config.AutoReforge = false
                    save()

                    notify(
                        "Auto Reforge",
                        "Select an inventory item first.",
                        4
                    )

                    M.UpdateStatus()
                    return
                end

                runWorker()
            end

            function M.StartSaved()
                if ctx.Config.AutoReforge then
                    task.defer(function()
                        task.wait(1.5)
                        runWorker()
                    end)
                end
            end

            function M.StartStatusLoop()
                task.spawn(function()
                    while true do
                        task.wait(
                            ctx.Config.AutoReforge
                            and 0.35
                            or 1.00
                        )
                        M.UpdateStatus()
                    end
                end)
            end

            M.Qualities = qualities

            return M
        end
